function splitLines(t){ return String(t||'').split(/\n+/).map(function(s){return s.trim();}).filter(function(s){return s.length;}); }
var QSTEM={
  '选择题':function(t,i){return '关于《'+t+'》，下列说法错误的是？';},
  '填空题':function(t,i){return '请补全与《'+t+'》相关的第 '+i+' 空：________';},
  '简答题':function(t,i){return '请说明《'+t+'》第 '+i+' 个关键步骤。';},
  '计算题':function(t,i){return '计算第 '+i+' 道《'+t+'》相关题目并写出过程。';},
  '论述题':function(t,i){return '论述《'+t+'》在实际中的应用（第 '+i+' 题）。';}
};
function parseSections(t){
  var raw=splitLines(t);
  if(!raw.length) raw=['选择题:10:2','填空题:5:3','简答题:3:10'];
  return raw.map(function(l){
    var p=l.split(/[:：]/);
    var type=String(p[0]||'').trim()||'简答题';
    var count=parseInt(p[1],10)||3; if(count<1)count=1; if(count>30)count=30;
    var pts=parseInt(p[2],10)||5; if(pts<1)pts=1; if(pts>50)pts=50;
    return {type:type, count:count, points:pts};
  });
}
function buildExam(o){
  o=o||{};
  var subject=String(o.subject||'通用').trim()||'通用';
  var grade=String(o.grade||'').trim();
  var topic=String(o.topic||'').trim()||'（待填写试卷主题）';
  var dur=parseInt(o.duration,10)||90; if(dur<10)dur=10; if(dur>300)dur=300;
  var secs=parseSections(o.sections);
  var lines=[], qn=0, totalPoints=0;
  lines.push('# 试卷：'+subject+(topic?'《'+topic+'》':''));
  lines.push('');
  lines.push('- 适用学段：'+(grade||'不限')+'　考试时长：'+dur+' 分钟');
  lines.push('');
  secs.forEach(function(s,si){
    var def=QSTEM[s.type]||function(t,i){return '请完成第 '+i+' 题。';};
    var secTotal=s.count*s.points; totalPoints+=secTotal;
    lines.push('## 第 '+(si+1)+' 部分　'+s.type+'（共 '+s.count+' 题，每题 '+s.points+' 分，合计 '+secTotal+' 分）');
    for(var i=1;i<=s.count;i++){ qn++; lines.push(qn+'. （'+s.points+' 分）'+def(topic,i)); }
    lines.push('');
  });
  lines.push('## 总分：'+totalPoints+' 分');
  return {title:subject+' 试卷', sectionCount:secs.length, questionCount:qn, totalPoints:totalPoints, duration:dur, markdown:lines.join('\n')};
}
var EXPORTS={splitLines:splitLines, parseSections:parseSections, buildExam:buildExam};

if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
if (typeof window !== 'undefined') { window.ExamForgePure = EXPORTS; }
